class Home {
  + Name : string
}

class Department {
  + Name : string
}

class Room {
  + Number : int
}

class Bed {
  + Category : string
  + Price : double
}

class Inhabitant {
  + Name : string
  + RegistrationDate : date
  + NeedsHelpForEating : boolean
  + NeedsHelpForDressing : boolean
  + NeedsHelpForPersonalCare : boolean
}

class StayCategory {
  + Type : string
  + Price : double
}

class Proposal {
  + Status : string
  + AcceptanceDate : date
}

class Invoice {
  + Number : int
  + Total : double
  + OutstandingAmount : double
  + PaymentReceived : boolean
}

class CreditNote {}

Home "1" -- "0..*" Department
Department "1" -- "0..*" Room
Room "1" -- "0..*" Bed
Inhabitant "1" -- "0..*" StayCategory
StayCategory "1" -- "0..*" Proposal
Proposal "1" -- "0..*" Inhabitant
Inhabitant "1" -- "0..*" Invoice

@enduml

